from services.db import connect
from services.xirr import xirr
from typing import List, Dict, Optional

def get_active_holdings() -> List[Dict]:
    db = connect()
    cursor = db.cursor()
    cursor.execute("SELECT * FROM active_holdings")
    return cursor.fetchall()

def get_latest_prices() -> Dict[str, float]:
    db = connect()
    cursor = db.cursor()
    cursor.execute("SELECT symbol, price FROM latest_prices")
    return {row[0]: row[1] for row in cursor.fetchall()}

def get_price_history() -> List[Dict]:
    db = connect()
    cursor = db.cursor()
    cursor.execute("SELECT * FROM price_history")
    return cursor.fetchall()

def calculate_current_value(holdings: List[Dict], prices: Dict[str, float]) -> float:
    value = 0.0
    excluded = []
    for holding in holdings:
        symbol = holding['symbol']
        if symbol in prices:
            value += holding['units'] * prices[symbol]
        else:
            excluded.append(holding)
    return value, excluded

def calculate_gain_loss(current_value: float, initial_value: float) -> float:
    return current_value - initial_value

def calculate_weight(holding: Dict, total_value: float) -> float:
    return holding['units'] * holding['price'] / total_value

def calculate_allocation(holding: Dict, asset_classes: List[str], geographies: List[str]) -> Dict:
    allocation = {'asset_class': 0.0, 'geography': 0.0}
    total_value = sum(holding['units'] * holding['price'] for holding in holdings)
    for asset_class in asset_classes:
        if holding['asset_class'] == asset_class:
            allocation['asset_class'] += calculate_weight(holding, total_value)
    for geography in geographies:
        if holding['geography'] == geography:
            allocation['geography'] += calculate_weight(holding, total_value)
    return allocation

def calculate_xirr(holdings: List[Dict], prices: Dict[str, float]) -> float:
    cash_flows = []
    for holding in holdings:
        symbol = holding['symbol']
        if symbol in prices:
            cash_flows.append((holding['purchase_date'], -holding['units'] * holding['price']))
            cash_flows.append((holding['sell_date'], holding['units'] * prices[symbol]))
    return xirr(cash_flows)

def calculate_concentration(holdings: List[Dict]) -> float:
    total_value = sum(holding['units'] * holding['price'] for holding in holdings)
    top_holdings = sorted(holdings, key=lambda x: x['units'] * x['price'], reverse=True)
    top_value = sum(holding['units'] * holding['price'] for holding in top_holdings[:5])
    return top_value / total_value

def calculate_fund_overlap(holdings: List[Dict]) -> Dict:
    overlap_matrix = {}
    for i in range(len(holdings)):
        for j in range(i + 1, len(holdings)):
            symbol_i = holdings[i]['symbol']
            symbol_j = holdings[j]['symbol']
            if symbol_i in overlap_matrix:
                overlap_matrix[symbol_i][symbol_j] = 1
            else:
                overlap_matrix[symbol_i] = {symbol_j: 1}
            if symbol_j in overlap_matrix:
                overlap_matrix[symbol_j][symbol_i] = 1
            else:
                overlap_matrix[symbol_j] = {symbol_i: 1}
    return overlap_matrix

def portfolio_vs_benchmark() -> Dict:
    db = connect()
    cursor = db.cursor()
    cursor.execute("SELECT * FROM portfolio_vs_benchmark")
    return {'state': 'ok', 'series': cursor.fetchall()}

def rolling_returns(window: int) -> Dict:
    db = connect()
    cursor = db.cursor()
    cursor.execute("SELECT * FROM rolling_returns WHERE window = ?", (window,))
    return {'state': 'ok', 'series': cursor.fetchall()}

def drawdown() -> Dict:
    db = connect()
    cursor = db.cursor()
    cursor.execute("SELECT * FROM drawdown")
    return {'state': 'ok', 'series': cursor.fetchall()}
